shader.source:
// rox preset: Shadow.
//
// A drop shadow cast by the panel's own content. The `mask` binding is the
// body's draws isolated on transparency, so the shadow hugs glyphs, icons
// and controls exactly, whatever the backdrop looks like: the soft pass
// blurs that coverage at half size, and the out pass lays it down dark,
// shifted, and cut away under the content itself, so the ink stays exactly
// as bright as it was drawn.
//
// Output is premultiplied, and most of the rect stays transparent: this is
// an overlay in the same sense Sheen is, riding a panel (or a whole group)
// that already draws.
//
// @overlay
// @slot 0: soften
// @slot 1: strength
// @slot 2: drop
// @slot 3: lift

// A knob resting at zero means "unrouted, unset", so each one has a spot
// the shadow defaults to rather than vanishing.
fn shadow_knob(value: f32, rest: f32) -> f32 {
    return mix(rest, value, step(0.001, value));
}

// @pass soft: 0.5

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let soften = shadow_knob(params.signals[0].x, 0.35);
    // Tap spread in uv, off the pass's own half resolution: the half-size
    // target and its bilinear reads are the inner half of the blur.
    let res = max(params.resolution, vec2<f32>(1.0));
    let reach = vec2<f32>(soften * 12.0) / res;

    var cover = textureSampleLevel(mask, samp, uv, 0.0).a;
    var weight = 1.0;
    for (var i = 0u; i < 8u; i = i + 1u) {
        let a = f32(i) * 0.78539816;
        let dir = vec2<f32>(cos(a), sin(a));
        cover = cover + textureSampleLevel(mask, samp, uv + dir * reach * 0.5, 0.0).a * 0.75;
        cover = cover + textureSampleLevel(mask, samp, uv + dir * reach, 0.0).a * 0.35;
        weight = weight + 1.1;
    }
    return vec4<f32>(0.0, 0.0, 0.0, cover / weight);
}

// @pass out

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let strength = shadow_knob(params.signals[0].y, 0.55);
    let drop = shadow_knob(params.signals[0].z, 0.18);
    let lift = clamp(params.signals[0].w, 0.0, 1.0);

    // The shadow sits below its caster, so its coverage is read from above
    // the pixel in hand.
    let res = max(params.resolution, vec2<f32>(1.0));
    let offset = vec2<f32>(0.0, drop * 14.0) / res;
    let spread = textureSampleLevel(soft, samp, uv - offset, 0.0).a;

    // The cutout: this pixel's own ink wins over any shadow behind it, and
    // an anti-aliased edge wins by exactly its coverage.
    let ink = textureSampleLevel(mask, samp, uv, 0.0).a;
    let shade = smoothstep(0.0, 0.85, spread) * strength * (1.0 - ink);

    // Black shadow at rest; the lift walks it toward white for the looks
    // where a dark backdrop wants a halo instead.
    let tone = vec3<f32>(lift);
    return vec4<f32>(tone * shade, shade);
}

shaders.source:
// rox shader: Glass. A glass frame over whatever panel wears it: an edge
// band where the picture bows inward and frosts, while everything
// inside the band passes through untouched, pixel for pixel, so the
// content stays exactly as readable as it was. The
// middle is not glass on purpose; this is edges and corners only.
//
// The pane either fills the panel's rect or hugs the picture itself,
// which is the fit slot: 0 the rect, 1 the picture. The picture's shape
// arrives as user_meta[1].w, the host's word on what the panel drew:
// width over height letterboxed centered, negative when it fills the
// rect, and zero from a panel that never says, which falls back to the
// centered square. Radius, band width, and the optics all ride slots,
// and the bundle's manual values are the tuning. Everything resting at zero is a
// square pane with a hairline band and no optics, so tune or route
// before expecting much.
//
// The pointer is a thumb resting near the glass. The stretch of rim
// within its reach bows deeper and frosts harder, the picture
// refracting under the press, and the press falls off smoothly with
// distance, so dragging the hand around the cover rolls a soft lens
// along the frame. Presence swells it in when the hand arrives and
// eases it back out when the hand goes still, both ends shaped by the
// host, so the glass never pops. Nothing brightens: the whole answer
// is refraction. Nothing reads the clock, so a still pointer costs
// nothing.
//
// The feather is the melt: past the rim the frost keeps reading, wider
// than anywhere inside, and fades out across the feather's reach, so the
// pane dissolves into whatever sits around it instead of ending on a
// line. At zero the rim is back to a clean edge.
//
// @overlay
// @slot 0: radius
// @slot 1: band
// @slot 2: bend
// @slot 3: frost
// @slot 5: fit
// @slot 6: press
// @slot 7: feather

// The composed frame under the pane, clamped so a bent read can't leave
// the rect.
fn glass_read(at: vec2<f32>) -> vec3<f32> {
    let inside = clamp(at, vec2<f32>(0.0), vec2<f32>(1.0));
    return textureSampleLevel(screen, samp, inside, 0.0).rgb;
}

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let radius_k = clamp(params.signals[0].x, 0.0, 1.0);
    let band_k = clamp(params.signals[0].y, 0.0, 1.0);
    let bend_k = clamp(params.signals[0].z, 0.0, 1.0);
    let frost_k = clamp(params.signals[0].w, 0.0, 1.0);
    let fit = clamp(params.signals[1].y, 0.0, 1.0);
    let press_k = clamp(params.signals[1].z, 0.0, 1.0);
    let feather_k = clamp(params.signals[1].w, 0.0, 1.0);

    let res = max(params.resolution, vec2<f32>(1.0));
    let base = glass_read(uv);

    // The pane's half-size: the whole rect, eased toward what the panel
    // says it drew. A published shape is the letterboxed picture's own
    // rect, negative says the picture fills the panel, and no word falls
    // back to the centered square.
    let shape = params.user_meta[1].w;
    var content = vec2<f32>(min(res.x, res.y) * 0.5);
    if (shape > 0.0) {
        let wide = min(res.x, res.y * shape);
        content = vec2<f32>(wide, wide / shape) * 0.5;
    } else if (shape < 0.0) {
        content = res * 0.5;
    }
    let half = mix(res * 0.5, content, fit);
    let radius = min(radius_k * 64.0, min(half.x, half.y));
    let band = max(band_k * 48.0, 2.0);

    // Rounded-box signed distance in device pixels, negative inside.
    let p = (uv - vec2<f32>(0.5)) * res;
    let q = abs(p) - half + vec2<f32>(radius);
    let out_q = max(q, vec2<f32>(0.0));
    let dist = length(out_q) + min(max(q.x, q.y), 0.0) - radius;

    // The band, easing in at its inner rim; past the outer rim the melt
    // takes over, fading across the feather's reach so the pane blurs
    // out into its surroundings rather than ending on a line.
    let feather = max(feather_k * 48.0, 0.5);
    let weight = smoothstep(-band - 1.0, -band + 1.0, dist)
        * (1.0 - smoothstep(0.0, feather, dist));
    if (weight <= 0.0) {
        return vec4<f32>(base, 1.0);
    }

    // Depth into the band, 0 at the inner rim to 1 at the outer, and the
    // way the nearest rim faces. Deep on a straight stretch the nearer
    // axis is the normal; out past a corner it swings around the arc.
    // Past the rim it holds at 1, so the melt zone frosts and bends at
    // full depth while the weight fades it out.
    let t = clamp(1.0 + dist / band, 0.0, 1.0);
    var n = vec2<f32>(0.0);
    if (max(q.x, q.y) < 0.0) {
        if (q.x > q.y) {
            n = vec2<f32>(sign(p.x), 0.0);
        } else {
            n = vec2<f32>(0.0, sign(p.y));
        }
    } else {
        n = normalize(out_q) * sign(p);
    }

    // The press: how hard the hand bears on this stretch of rim. The
    // reach falls off exponentially with the gap between pointer and
    // pixel, about a third of the pane across, so the lens stays local
    // to the hand, and presence swells the whole thing in and out with
    // both ends eased by the host.
    let here = clamp(params.user_meta[1].z, 0.0, 1.0);
    let hand = params.mouse.xy - res * 0.5;
    let reach = exp(-length(hand - p) / (0.35 * (half.x + half.y)));
    let press = reach * here * press_k;

    // The optics: the picture pulled from deeper inside the pane, harder
    // toward the rim, which is what reads as thickness, under a frost
    // that widens the same way. The press bows the nearby rim up to
    // forty pixels deeper whatever the resting bend says, which is the
    // refraction the hand actually sees, and because the reach is
    // smooth the melt swells under the pointer instead of wobbling.
    let pull = n * (bend_k * 24.0 + 40.0 * press) * t * t;
    let lens = uv - pull / res;
    // Tap spacing grows with the square of the depth, so the inner band
    // stays near-sharp and the rim melts hard: at full frost the taps sit
    // 8px apart, a 16px reach either way, which is what smears the pane's
    // edge and its surroundings into one soft gradient over the feather.
    // Under the press the taps spread up to three quarters wider, so
    // the hand reads in the blur as well as the bend.
    var color = vec3<f32>(0.0);
    let spread = (frost_k * 8.0 * (1.0 + 0.75 * press) * t * t) / res;
    for (var x = -2; x <= 2; x = x + 1) {
        for (var y = -2; y <= 2; y = y + 1) {
            color = color + glass_read(lens + vec2<f32>(f32(x), f32(y)) * spread);
        }
    }
    color = color / 25.0;

    return vec4<f32>(mix(base, color, weight), 1.0);
}

// rox shader: Glass Slab. The drawer's sheet of glass, worn entirely on
// its face: no rim optics, no bent content, just the reflections. Two
// soft diagonal streaks ride the sheet, a whisper of light grades down
// it, and a glow drifts under the pointer. The hand is what animates
// it: the streaks travel as the pointer moves, the way reflections walk
// across a pane as it tilts, and a streak catches bright while the hand
// stands on its line. Everything is additive brightness a few percent
// tall, so the text under it stays text.
//
// Presence eases the whole reaction out: reflections drift home, the
// catch lets go, the glow fades, and the surface stops asking for
// frames. A parked pointer costs nothing.
//
// The phase slot is for a slow aggregate: routed there, the reflections
// sway across the sheet with the music's own time, through the wrap
// without a snap since it reads as sin. Nothing routed leaves them
// resting, which is the drawer's tuning; the backdrop is the wearer
// that routes it.
//
// @overlay
// @slot 0: sheen
// @slot 1: glint
// @slot 2: drift
// @slot 3: phase

const TAU: f32 = 6.28318530718;

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let sheen_k = clamp(params.signals[0].x, 0.0, 1.0);
    let glint_k = clamp(params.signals[0].y, 0.0, 1.0);
    let drift_k = clamp(params.signals[0].z, 0.0, 1.0);
    let phase = clamp(params.signals[0].w, 0.0, 1.0);

    let res = max(params.resolution, vec2<f32>(1.0));
    let p = (uv - vec2<f32>(0.5)) * res;
    let base = textureSampleLevel(screen, samp, uv, 0.0).rgb;

    // The pointer in sheet-centered pixels, and how much the hand still
    // counts for.
    let here = clamp(params.user_meta[1].z, 0.0, 1.0);
    let hand = params.mouse.xy - res * 0.5;
    let gap = length(hand - p);

    // The tilt: where the hand stands on the sheet, scaled by the drift
    // slot and eased out with presence, so the reflections walk with the
    // pointer and drift home when it leaves.
    let tilt = clamp(hand / res, vec2<f32>(-0.6), vec2<f32>(0.6)) * here * drift_k * 2.0;

    // The streak coordinate: a diagonal across the sheet, slid by the
    // tilt and swayed by the phase. Evaluated once for this pixel and
    // once for the hand, since a streak catches bright while the hand
    // stands on its line; both carry the sway, so the catch stays true
    // while the pattern moves.
    let sway = 0.30 * sin(TAU * phase);
    let s = (p.x - 0.45 * p.y) / res.x - 0.35 * tilt.x + 0.15 * tilt.y + sway;
    let h = (hand.x - 0.45 * hand.y) / res.x - 0.35 * tilt.x + 0.15 * tilt.y + sway;
    let catch_a = 0.5 + 1.5 * exp(-pow((h + 0.12) / 0.14, 2.0)) * here;
    let catch_b = 0.5 + 1.5 * exp(-pow((h - 0.16) / 0.08, 2.0)) * here;
    let streaks = exp(-pow((s + 0.12) / 0.10, 2.0)) * catch_a
        + 0.6 * exp(-pow((s - 0.16) / 0.05, 2.0)) * catch_b;

    // Light grading down the sheet, and the glow under the hand.
    let grade = 0.5 - uv.y;
    let sigma = 0.4 * min(res.x, res.y);
    let glow = exp(-(gap * gap) / (2.0 * sigma * sigma));

    let face = (0.05 * streaks + 0.04 * grade) * sheen_k * 2.0
        + 0.06 * glow * here * glint_k * 2.0;
    return vec4<f32>(clamp(base + vec3<f32>(face), vec3<f32>(0.0), vec3<f32>(1.0)), 1.0);
}
